for blk in blocks:
    lines = blk.strip().splitlines()
    m = re.search(r'urn:buildgraph:tsref:([0-9a-f-]+)', lines[0] if lines else '')
    if m:
        for l in lines[1:]:
            mm = re.search(r'hasTimeseriesId\s+"([^"]+)"', l)
            if mm:
                tsref2tsid[m.group(1)] = mm.group(1)

# Now for each Air_Temperature_Sensor, find tsid and zone name
